CREATE OR REPLACE FUNCTION public.complete_learning_lesson(p_lesson text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE path text; sections integer; BEGIN SELECT parcours INTO path FROM public.profiles WHERE id=auth.uid(); IF path IS NULL THEN RAISE EXCEPTION 'Connectez-vous pour terminer cette leçon.'; END IF; IF EXISTS(SELECT 1 FROM public.learning_completions WHERE user_id=auth.uid() AND parcours=path AND lesson_id=p_lesson) THEN RETURN; END IF; SELECT cardinality(body) INTO sections FROM public.learning_lessons WHERE id=p_lesson AND published AND path=ANY(pathways); IF sections IS NULL OR sections=0 THEN RAISE EXCEPTION 'Le contenu de cette leçon est indisponible pour votre parcours.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.learning_reading_positions WHERE user_id=auth.uid() AND parcours=path AND lesson_id=p_lesson AND section_index=sections-1) THEN RAISE EXCEPTION 'Lisez toutes les sections avant de terminer la leçon.'; END IF; INSERT INTO public.learning_completions(user_id,parcours,lesson_id) VALUES(auth.uid(),path,p_lesson) ON CONFLICT DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION public.save_learning_reading_position(p_lesson text,p_section integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE path text; n integer; BEGIN SELECT parcours INTO path FROM public.profiles WHERE id=auth.uid(); IF path IS NULL THEN RAISE EXCEPTION 'Connectez-vous pour continuer.'; END IF; SELECT cardinality(body) INTO n FROM public.learning_lessons WHERE id=p_lesson AND published AND path=ANY(pathways); IF n IS NULL OR n=0 OR p_section<0 OR p_section>=n THEN RAISE EXCEPTION 'Section indisponible.'; END IF; INSERT INTO public.learning_reading_positions(user_id,parcours,lesson_id,section_index) VALUES(auth.uid(),path,p_lesson,p_section) ON CONFLICT(user_id,parcours,lesson_id) DO UPDATE SET section_index=excluded.section_index,updated_at=now(); END $$;